meta={'candidate_sha':candidate,'suite_sha':get(['git','rev-parse','HEAD']),'versions':versions,'binary_sha256':{e:sha(c[0]) for e,c in cmd.items()},'compiler':get(['g++','--version']),'go_compiler_sha256':sha(R/'work/tools/go/bin/go'),'uname':get(['uname','-a']),'cpu':get(['lscpu']),'meminfo':Path('/proc/meminfo').read_text(),'filesystem':get(['findmnt','-T',str(R),'-o','SOURCE,FSTYPE,OPTIONS']),'affinity':sorted(os.sched_getaffinity(0))[:4],'build_flags':'Nift exact parent-built normal O2 CLI unchanged; frozen Go adapter default optimized Go1.27.2','diagnostic':'one fresh walk request per engine/size, postexec /procVmHWM after exact full response before exit','cells':15,'warmups':0,'host_role':'same g6-standard-4 after website official timing/audits; separate diagnostic'}
